div.div:
{



    evmNonce: Uint<64>,


    gasLimit: Uint<64>,


    maxFeePerGas: Uint<128>,


    maxPriorityFeePerGas: Uint<128>,



depositRequest: {


erc20Address: Bytes<20>,


amount: Uint<128>


},


}

Calculate Deposit Key
// see erc20-vault.compact
key = refundCommitment(
callerSecretKey(),
depositBinder(evmNonce)
)

Prepare Deposit
-
name = "midnight/deposits/${key}"
- args = {
evmNonce: evmNonce,
gasLimit: gasLimit,
maxFeePerGas: maxFeePerGas,
maxPriorityFeePerGas: maxPriorityFeePerGas,
depositRequest: {
erc20Address: erc20Address,
amount: amount
},
}
